\noindent \mbox{\em Proof.\hspace*{2mm}}
See Segre \cite[II, \S 6 Observation IV ]{seg1959}
or Homma-Kim \cite[Remark 1.2]{hom-kim2009}.
\hfill \mbox{$  \Box $}

\noindent \mbox{\em Proof.\hspace*{2mm}}
Suppose $S$ does not contain any ${\Bbb F}_q$-lines.
Let $H$ be any ${\Bbb F}_q$-plane in ${\Bbb P}^3$.
Then $S\cap H$ is a plane curve of degree $d$ over ${\Bbb F}_q$
in $H = {\Bbb P}^2$, and has no ${\Bbb F}_q$-line as a component.
Hence
\begin{equation}
 N_q(S\cap H) \leq
  \left\{
      \begin{array}{cl}
       (d-1)q +1 & \mbox{\rm if $(d,q) \neq (4,4)$}\\
       14        & \mbox{\rm if $(d,q) = (4,4)$}
      \end{array}
  \right.
\end{equation}
by Lemma~\ref{sziklai_bound}.
In a term of \cite{hom2012},
defining the $s$-degree $\delta$ of $S({\Bbb F}_q)$ by
\[
\delta = \max \{ N_q(S\cap H) \mid \mbox{\rm $H$ is an ${\Bbb F}_q$-plane} \}, 
\]
we have
\[
N_q(S) \leq (\delta -1)q + 1 +
\left\lfloor
\frac{\delta -1}{q +1}
     \right\rfloor
\]
by \cite[Proposition 2.2]{hom2012}.
Hence if $(d,q) \neq (4,4)$, then
\begin{eqnarray*}
 N_q(S) & \leq & (d-1)q^2 +1 + \left\lfloor
\frac{(d -1)q}{q +1}
     \right\rfloor\\
     &=& (d-1)q^2 +1 + \left\lfloor
\frac{(d -2)(q+1)+q+2-d}{q +1}
     \right\rfloor\\
     &=& (d-1)(q^2+1) \, {\rm ;}
\end{eqnarray*}
and if $(d,q) = (4,4)$, then $N_q(S) \leq 55$.
In either case, $N_q(S)$ can't be
$(d-1)q^2 + dq +1.$
\hfill \mbox{$  \Box $}

\begin{definition}
Let $l_1, \dots , l_d$ be ${\Bbb F}_q$-lines in ${\Bbb P}^3$
with $d \geq 2$.
The union of those $d$-lines $Z = \cup_{i=1}^d l_i$
is called a planar ${\Bbb F}_q$-pencil of degree $d$
if those $d$-lines lie on a plane simultaneously
and $l_1 \cap \dots \cap l_d \neq \emptyset$.
The ${\Bbb F}_q$-point $\{v_Z\} = l_1 \cap \dots \cap l_d$
is called the vertex of $Z$.
\end{definition}

\begin{notation}
For an ${\Bbb F}_q$-line $l$ of ${\Bbb P}^3$,
the set of ${\Bbb F}_q$-planes containing the line $l$
is denoted by $\check{l}({\Bbb F}_q)$.
\end{notation}

\noindent \mbox{\em Proof.\hspace*{2mm}}
From Lemma~\ref{contains_line} and Lemma~\ref{planar_pencil} (i),
there is a line $l$ on $S$ containing $P$.

Indeed the existence of an ${\Bbb F}_q$-line $l'$ on $S$
is guaranteed by Lemma~\ref{contains_line};
if the point $P$ in question lies on $l'$, there is nothing to do;
when $P \not\in l'$,
consider the ${\Bbb F}_q$-plane $H'$ containing $l'$ and $P$,
then $S \cap H'$ is a planar ${\Bbb F}_q$-pencil
by Lemma~\ref{planar_pencil} (i), which contains $P$;
hence there is a line $l$ on $S$ containing $P$.

Hence, by (ii) of Lemma~\ref{planar_pencil}
there is a desired ${\Bbb F}_q$-plane,
and such a plane is uniquely determined by $P$.
\hfill \mbox{$  \Box $}

